import sympy

# Top-level setup
Z = sympy.S.Integers

def get_generator(gen):
    """Extract a single generator for the ideal from a list of generators."""
    if isinstance(gen, (list, tuple, set)) or type(gen).__name__ in ('Tuple', 'List', 'Set'):
        gen = list(gen)
        if not gen:
            return sympy.S.Zero
        g = sympy.sympify(gen[0])
        for x in gen[1:]:
            g = sympy.gcd(g, sympy.sympify(x))
        return g
    return sympy.sympify(gen)

def is_prime_ideal(p):
    """Check if the ideal generated by p is a prime ideal."""
    if p == 0:
        return True
    if isinstance(p, int) or (hasattr(p, 'is_integer') and p.is_integer):
        return sympy.isprime(int(abs(p)))
    try:
        poly = sympy.Poly(p)
        return poly.is_irreducible
    except Exception:
        return False

def ideals_equal(p, q):
    """Check if the ideals generated by p and q are equal."""
    if p == 0 and q == 0:
        return True
    if p == 0 or q == 0:
        return False
    if (isinstance(p, int) or (hasattr(p, 'is_integer') and p.is_integer)) and \
       (isinstance(q, int) or (hasattr(q, 'is_integer') and q.is_integer)):
        return abs(p) == abs(q)
    try:
        rat = sympy.cancel(p / q)
        return rat.is_constant()
    except Exception:
        return False

def strictly_contains(q, p):
    """Check if the ideal quotient (q:p) strictly contains the ideal (q)."""
    if q == 0:
        return p == 0
    try:
        g = sympy.gcd(p, q)
        if isinstance(g, int) or (hasattr(g, 'is_integer') and g.is_integer):
            return abs(g) > 1
        else:
            return not sympy.Poly(g).is_constant()
    except Exception:
        return False

def conditions(witness):
    try:
        if isinstance(witness, dict):
            p_raw = witness.get('P', witness.get('p'))
            q_raw = witness.get('Q', witness.get('q'))
        elif isinstance(witness, (tuple, list)) or type(witness).__name__ in ('Tuple', 'List'):
            if len(witness) == 3:
                _, p_raw, q_raw = witness
            elif len(witness) == 2:
                p_raw, q_raw = witness
            else:
                return [False, False, False, False]
        else:
            return [False, False, False, False]
            
        p = get_generator(p_raw)
        q = get_generator(q_raw)
    except Exception:
        return [False, False, False, False]

    # H1: R is a commutative ring
    # We assume the ring is Z or K[x], which are commutative.
    h1 = True

    # H2: P is a prime ideal in R
    try:
        h2 = bool(is_prime_ideal(p))
    except Exception:
        h2 = False

    # H3: Q \neq P
    try:
        h3 = not bool(ideals_equal(p, q))
    except Exception:
        h3 = False

    # neg_Q: (Q:P) does NOT strictly contain Q
    try:
        neg_q = not bool(strictly_contains(q, p))
    except Exception:
        neg_q = False

    return [h1, h2, h3, neg_q]

CONDITION_LABELS = [
    "H_1: R is a commutative ring",
    "H_2: P is a prime ideal in R",
    "H_3: Q \\neq P",
    "¬Q: (Q:P) does not strictly contain Q"
]

N_HYP = 3
